using System;
using System.Collections;
using System.Collections.Generic;
using DG.Tweening;
using FMODUnity;
using LittleLeo.Variables;
using NaughtyAttributes;
using UnityEngine;

namespace Astrea;

public class OrionAstrarium : MonoBehaviour
{
	[Header("Orbs Settings")]
	[SerializeField]
	private bool startBattleRandomPosition;

	[Header("Star Abilities")]
	[SerializeField]
	private List<StarAbility> starAbilities;

	[Header("Moving Orbs Animation")]
	[SerializeField]
	private float starAbilityMovementDuration;

	[SerializeField]
	private AnimationCurve starAbilityMovementCurve;

	[SerializeField]
	private float starAbilityOnBackScale;

	[SerializeField]
	private float starAbilityOnBackDepth;

	[SerializeField]
	private float starAbilityOnFrontScale;

	[SerializeField]
	private float starAbilityOnFrontDepth;

	[Header("Moving Orbs Positioning")]
	[SerializeField]
	private int[] startAbilityAngles;

	[SerializeField]
	private Transform centerTransform;

	[SerializeField]
	private float radiusX;

	[SerializeField]
	private float radiusY;

	[Header("Components")]
	[SerializeField]
	private StarAbilityInstance[] starAbilityInstances;

	[Header("Assets")]
	[SerializeField]
	private StarAbilityReference starAbilityReference;

	[SerializeField]
	private MapHandler mapHandler;

	[Header("Evil Constellation")]
	[SerializeField]
	private bool evilConstellation;

	[Header("Enemies")]
	[SerializeField]
	private CurrentCorruptedAnimals currentCorruptedAnimals;

	[Header("Orion Runic Circle")]
	[SerializeField]
	private GameObject orionRunicCirclePrefab;

	[Header("SFX")]
	[SerializeField]
	private EventReference moveOrbsSFX;

	[SerializeField]
	private EventReference activateOrbSFX;

	[Header("Joystick")]
	[SerializeField]
	private OrionUnitDetailJoystickInput orionUnitDetailJoystickInput;

	[Header("Achievement")]
	[SerializeField]
	[HideIf("evilConstellation")]
	private AchievementData theworldgoesroundAchievementData;

	[SerializeField]
	private IntReference activeStarIndexIntReference;

	private Vector3[] starAbilityPositions;

	private bool lastStarActivationWithDelay;

	private int activeStarIndex => activeStarIndexIntReference.Value;

	private StarAbilityInstance activeStarAbilityInstance => starAbilityInstances[activeStarIndex];

	public void OnActivateLastStarActivationWithDelay()
	{
		lastStarActivationWithDelay = true;
	}

	private void Start()
	{
		UnityEngine.Object.Instantiate(orionRunicCirclePrefab);
		starAbilityPositions = new Vector3[starAbilityInstances.Length];
		for (int i = 0; i < starAbilityPositions.Length; i++)
		{
			starAbilityPositions[i] = starAbilityInstances[i].transform.position;
			if ((evilConstellation && i >= 2) || (!evilConstellation && i == 1) || i == 2)
			{
				starAbilityInstances[i].SetDefaultScale(starAbilityOnBackScale);
			}
			else
			{
				starAbilityInstances[i].SetDefaultScale(starAbilityOnFrontScale);
			}
			starAbilityInstances[i].SetCurrentAngle(startAbilityAngles[i]);
			starAbilityInstances[i].transform.localPosition = GetPointOnCirclePerimeter(startAbilityAngles[i], starAbilityInstances[i].transform.localPosition.z);
		}
		for (int j = 0; j < starAbilityInstances.Length; j++)
		{
			starAbilityInstances[j].Initialize(starAbilities[j]);
		}
		StartCoroutine(InitializeOrionOrbsCoroutineBattleSceneInitialize());
	}

	private IEnumerator InitializeOrionOrbsCoroutineBattleSceneInitialize()
	{
		if (activeStarIndexIntReference.Value != 0)
		{
			int movementsNeededToStartingPosition = starAbilityInstances.Length + activeStarIndexIntReference.Value;
			if (movementsNeededToStartingPosition > 4)
			{
				movementsNeededToStartingPosition -= starAbilityInstances.Length;
			}
			for (int i = 0; i < movementsNeededToStartingPosition; i++)
			{
				MoveOrbsAnimation(movingClockwise: true);
				yield return new WaitForSeconds(0.001f);
			}
		}
		starAbilityReference.SetValue(activeStarAbilityInstance.StarAbility);
		if (ReferenceSingleton<InputManager>.Instance.IsJoystickBeingUsed)
		{
			orionUnitDetailJoystickInput.InitializeZoomableInstance(starAbilityInstances);
		}
	}

	[Button(null)]
	private void MoveOrbsOneTime()
	{
		StartCoroutine(MoveOrbsCoroutine(1));
	}

	public void OnInitializeOrionOrbs()
	{
		StartCoroutine(InitializeOrionOrbsCoroutineStartOfBattle());
	}

	private IEnumerator InitializeOrionOrbsCoroutineStartOfBattle()
	{
		int num = 0;
		if (startBattleRandomPosition)
		{
			RandomUtilities.SetUnityEngineRandomInitStateSeed(mapHandler.GetSeedWithCurrentMapPlayerTracker());
			num = RandomUtilities.RandomIntWithSeed(starAbilityInstances.Length);
		}
		starAbilityReference.SetValue(starAbilityInstances[num].StarAbility);
		if (activeStarIndex != num)
		{
			int movementsNeededToStartingPosition = starAbilityInstances.Length - activeStarIndex + num;
			if (movementsNeededToStartingPosition > 4)
			{
				movementsNeededToStartingPosition -= starAbilityInstances.Length;
			}
			for (int i = 0; i < movementsNeededToStartingPosition; i++)
			{
				activeStarIndexIntReference.ChangeAmount(1);
				if (activeStarIndex == starAbilityInstances.Length)
				{
					activeStarIndexIntReference.SetValue(0);
				}
				else if (activeStarIndex == -1)
				{
					activeStarIndexIntReference.SetValue(starAbilityInstances.Length - 1);
				}
				MoveOrbsAnimation(movingClockwise: true);
				yield return new WaitForSeconds(starAbilityMovementDuration);
			}
		}
		Debug.Log("InitializeOrionOrbs - activeStarIndex: " + activeStarIndex);
		Debug.Log("InitializeOrionOrbs - activeStarAbilityInstance: " + activeStarAbilityInstance.StarAbility);
	}

	public IEnumerator MoveOrbsCoroutine(int movementAmount)
	{
		bool movingClockwise = movementAmount > 0;
		movementAmount = Mathf.Abs(movementAmount);
		for (int i = 0; i < movementAmount; i++)
		{
			if (!evilConstellation)
			{
				ReferenceSingleton<AssetsReference>.Instance.PlayerRunData.OrbsMovedAmount++;
				ReferenceSingleton<AssetsReference>.Instance.PlayerRunData.OrbsMovedWholeBattleAmount++;
				if (!theworldgoesroundAchievementData.IsUnlocked() && ReferenceSingleton<AssetsReference>.Instance.PlayerRunData.OrbsMovedWholeBattleAmount >= theworldgoesroundAchievementData.AchievementVariableAmount)
				{
					theworldgoesroundAchievementData.Unlock();
				}
			}
			else if (!currentCorruptedAnimals.IsAnyEnemyActive())
			{
				break;
			}
			activeStarAbilityInstance.OnExitingStar();
			int amount = (movingClockwise ? 1 : (-1));
			activeStarIndexIntReference.ChangeAmount(amount);
			if (activeStarIndex == starAbilityInstances.Length)
			{
				activeStarIndexIntReference.SetValue(0);
			}
			else if (activeStarIndex == -1)
			{
				activeStarIndexIntReference.SetValue(starAbilityInstances.Length - 1);
			}
			MoveOrbsAnimation(movingClockwise);
			if (!evilConstellation)
			{
				ReferenceSingleton<OrionOmensHandler>.Instance.OnActivateShootingStarOmen();
				starAbilityReference.SetValue(activeStarAbilityInstance.StarAbility);
				ReferenceSingleton<OrionOmensHandler>.Instance.ActivateHeartFragmentMovingOmen();
				ReferenceSingleton<SFXHandler>.Instance.PlaySFX(moveOrbsSFX);
			}
			else
			{
				starAbilityReference.SetValue(activeStarAbilityInstance.StarAbility);
			}
			yield return new WaitForSeconds(starAbilityMovementDuration);
			if (currentCorruptedAnimals.IsAnyEnemyActive())
			{
				activeStarAbilityInstance.OnEnteringStar();
				yield return new WaitForSeconds(0.5f);
				if (!currentCorruptedAnimals.IsAnyEnemyActive())
				{
					break;
				}
				continue;
			}
			break;
		}
	}

	public IEnumerator MoveOrbsBackAndForthCoroutine(int movementAmount)
	{
		for (int i = 0; i < movementAmount; i++)
		{
			yield return StartCoroutine(MoveOrbsCoroutine(1));
			if (currentCorruptedAnimals.IsAnyEnemyActive())
			{
				yield return StartCoroutine(MoveOrbsCoroutine(-1));
				if (!currentCorruptedAnimals.IsAnyEnemyActive())
				{
					break;
				}
				continue;
			}
			break;
		}
	}

	private void MoveOrbsAnimation(bool movingClockwise)
	{
		for (int i = 0; i < starAbilityInstances.Length; i++)
		{
			int num = i - activeStarIndex;
			if (num <= -1)
			{
				num += starAbilityInstances.Length;
			}
			MoveOrbToPosition(i, num, movingClockwise);
			ScaleOrb(i, num);
			if (evilConstellation)
			{
				SetDepthEvilConstellation(i, num, movingClockwise);
			}
			else
			{
				SetDepth(i, num, movingClockwise);
			}
		}
	}

	private void MoveOrbToPosition(int i, int newIndex, bool movingClockwise)
	{
		float currentAngle = starAbilityInstances[i].CurrentAngle;
		if (movingClockwise && currentAngle == 135f)
		{
			currentAngle = -225f;
		}
		else if (!movingClockwise && currentAngle == -135f)
		{
			currentAngle = 225f;
		}
		int newAngle = startAbilityAngles[newIndex];
		Transform starAbilityTransform = starAbilityInstances[i].transform;
		StartCoroutine(CoroutineUtility.CurveRoutine(starAbilityMovementDuration, starAbilityMovementCurve, delegate(float t, float v)
		{
			starAbilityTransform.localPosition = GetPointOnCirclePerimeter(Mathf.Lerp(currentAngle, newAngle, v), starAbilityTransform.localPosition.z);
		}));
		starAbilityInstances[i].SetCurrentAngle(newAngle);
	}

	private Vector3 GetPointOnCirclePerimeter(float angle, float posZ)
	{
		Vector3 result = default(Vector3);
		result.x = centerTransform.localPosition.x + radiusX * Mathf.Sin(angle * (MathF.PI / 180f));
		result.y = centerTransform.localPosition.y + radiusY * Mathf.Cos(angle * (MathF.PI / 180f));
		result.z = posZ;
		return result;
	}

	private void ScaleOrb(int i, int newIndex)
	{
		float num = (((!evilConstellation || newIndex < 2) && (evilConstellation || newIndex != 1) && newIndex != 2) ? starAbilityOnFrontScale : starAbilityOnBackScale);
		starAbilityInstances[i].SetDefaultScale(num);
		if (starAbilityInstances[i].transform.localScale != Vector3.one * num)
		{
			starAbilityInstances[i].transform.DOScale(Vector3.one * num, starAbilityMovementDuration);
		}
	}

	private void SetDepth(int i, int newIndex, bool movingClockwise)
	{
		switch (newIndex)
		{
		case 0:
		case 3:
			starAbilityInstances[i].transform.SetLocalZ(starAbilityOnFrontDepth);
			break;
		case 1:
			if (movingClockwise)
			{
				starAbilityInstances[i].transform.SetLocalZ(starAbilityOnBackDepth);
			}
			else
			{
				SetDepthZeroWithDelay(i);
			}
			break;
		case 2:
			if (movingClockwise)
			{
				SetDepthZeroWithDelay(i);
			}
			else
			{
				starAbilityInstances[i].transform.SetLocalZ(starAbilityOnBackDepth);
			}
			break;
		}
	}

	private void SetDepthEvilConstellation(int i, int newIndex, bool movingClockwise)
	{
		switch (newIndex)
		{
		case 0:
		case 1:
			starAbilityInstances[i].transform.SetLocalZ(starAbilityOnFrontDepth);
			break;
		case 2:
			if (movingClockwise)
			{
				starAbilityInstances[i].transform.SetLocalZ(starAbilityOnBackDepth);
			}
			else
			{
				SetDepthZeroWithDelay(i);
			}
			break;
		case 3:
			if (movingClockwise)
			{
				SetDepthZeroWithDelay(i);
			}
			else
			{
				starAbilityInstances[i].transform.SetLocalZ(starAbilityOnBackDepth);
			}
			break;
		}
	}

	private void SetDepthZeroWithDelay(int i)
	{
		InvokeAlternatives.Invoke(this, starAbilityMovementDuration * 2f / 3f, delegate
		{
			starAbilityInstances[i].transform.SetLocalZ(starAbilityOnBackDepth);
		});
	}

	public void OnEndPlayerTurn()
	{
		activeStarAbilityInstance.OnEndTurnStarAbility();
	}

	public void OnStartPlayerTurn()
	{
		activeStarAbilityInstance.OnStartTurnStarAbility();
	}

	public IEnumerator ActivateStarAbility(int activationAmount, StarAbility starAbilityToCast = null)
	{
		for (int i = 0; i < activationAmount; i++)
		{
			if (starAbilityToCast != null)
			{
				starAbilityToCast.OnActivateStarAbility();
			}
			else
			{
				activeStarAbilityInstance.OnActivateStarAbility();
			}
			if (!evilConstellation)
			{
				ReferenceSingleton<SFXHandler>.Instance.PlaySFX(activateOrbSFX);
			}
			yield return StartCoroutine(ActivateStarAbilityDelay(i, activationAmount));
			if (!currentCorruptedAnimals.IsAnyEnemyActive())
			{
				break;
			}
		}
	}

	private IEnumerator ActivateStarAbilityDelay(int i, int activationAmount)
	{
		if (lastStarActivationWithDelay)
		{
			yield return new WaitForSeconds(0.5f);
			if (i == activationAmount - 1)
			{
				lastStarActivationWithDelay = false;
			}
		}
		else if (i < activationAmount - 1)
		{
			yield return new WaitForSeconds(0.5f);
		}
		else
		{
			yield return new WaitForSeconds(0.25f);
		}
	}

	public IEnumerator ActivateAllStarsAbilitiesCoroutine(int activationAmount)
	{
		for (int i = 0; i < activationAmount; i++)
		{
			for (int j = 0; j < starAbilityInstances.Length; j++)
			{
				starAbilityInstances[j].OnActivateStarAbility();
			}
			if (!evilConstellation)
			{
				ReferenceSingleton<SFXHandler>.Instance.PlaySFX(activateOrbSFX);
			}
			yield return StartCoroutine(ActivateStarAbilityDelay(i, activationAmount));
			if (!currentCorruptedAnimals.IsAnyEnemyActive())
			{
				break;
			}
		}
	}

	public IEnumerator ActivateRandomStarAbilityCoroutine(int activationAmount)
	{
		for (int i = 0; i < activationAmount; i++)
		{
			starAbilityInstances.PickRandom().OnActivateStarAbility();
			if (!evilConstellation)
			{
				ReferenceSingleton<SFXHandler>.Instance.PlaySFX(activateOrbSFX);
			}
			yield return StartCoroutine(ActivateStarAbilityDelay(i, activationAmount));
			if (!currentCorruptedAnimals.IsAnyEnemyActive())
			{
				break;
			}
		}
	}

	public void OnCorruptedOrionPurified()
	{
		UnityEngine.Object.Destroy(base.transform.parent.gameObject);
	}
}
